head.b:skin:
/* Ahmed Al Gamal blog — same identity as ahmedalgamal.tech */
:root{
  --bg:#202734; --bg-dark:#1C2232; --bg-light:#262F42; --bg-lighter:#2E3850;
  --accent:#B7D894; --accent-soft:#E0F8C7;
  --text:#FFFFFF; --text-2:#C9D1DE; --muted:#9AA6BA;
  --line:rgba(201,209,222,.14); --line-strong:rgba(201,209,222,.24);
  --wa:#25D366;
  --display:"Bricolage Grotesque","Segoe UI",system-ui,sans-serif;
  --body:"Onest","IBM Plex Sans Arabic","Segoe UI",system-ui,sans-serif;
  --ar:"IBM Plex Sans Arabic","Onest",system-ui,sans-serif;
  --r-lg:22px; --r-md:14px; --r-sm:10px; --wrap:1160px;
  color-scheme:dark;
}
*{box-sizing:border-box}
html{scroll-behavior:smooth;overflow-x:clip}
body{margin:0;background:var(--bg);color:var(--text-2);font:400 17px/1.7 var(--body);-webkit-font-smoothing:antialiased;overflow-x:clip}
h1,h2,h3,h4{font-family:var(--display);color:var(--text);margin:0;letter-spacing:-.02em;text-wrap:balance}
[dir=rtl] h1,[dir=rtl] h2,[dir=rtl] h3,h1:lang(ar),h2:lang(ar){font-family:var(--ar);letter-spacing:0}
a{color:var(--accent)}
img{max-width:100%;height:auto}
:focus-visible{outline:2px solid var(--accent);outline-offset:3px;border-radius:6px}
.wrap{max-width:var(--wrap);margin:0 auto;padding-left:max(24px,env(safe-area-inset-left,0px));padding-right:max(24px,env(safe-area-inset-right,0px))}
main{position:relative;z-index:1}

/* Buttons */
.btn{display:inline-flex;align-items:center;justify-content:center;gap:8px;padding:13px 22px;border-radius:999px;border:1px solid transparent;font-weight:600;font-size:.97rem;text-decoration:none;cursor:pointer;transition:background .2s,color .2s,border-color .2s;white-space:nowrap;line-height:1.2;font-family:var(--body)}
.btn-sm{padding:9px 16px;font-size:.9rem}
.btn-wa,.btn-accent{background:var(--accent);color:var(--bg-dark)}
.btn-wa:hover,.btn-accent:hover{background:var(--accent-soft)}
.btn-ghost{background:transparent;color:var(--text);border-color:var(--line-strong)}
.btn-ghost:hover{border-color:var(--accent);color:var(--accent)}
.ico{width:18px;height:18px;flex:none}

/* Nav (same as site) */
.nav{position:sticky;top:env(safe-area-inset-top,0px);z-index:50;background:rgba(28,34,50,.9);backdrop-filter:blur(12px);-webkit-backdrop-filter:blur(12px);border-bottom:1px solid var(--line)}
.nav-in{display:flex;align-items:center;gap:20px;height:68px;direction:ltr}
.brand{white-space:nowrap;display:flex;align-items:center;gap:10px;color:var(--text);text-decoration:none;font-family:var(--display);font-weight:700;font-size:1.06rem}
.brand-mark{width:34px;height:34px;border-radius:10px;background:var(--accent);color:var(--bg-dark);display:grid;place-items:center;font-weight:800;font-size:.95rem;letter-spacing:-.04em}
.nav-menu{margin-left:auto;display:flex;align-items:center;gap:6px}
.nav-links{display:flex;gap:2px;list-style:none;margin:0;padding:0}
.nav-links a{white-space:nowrap;display:block;color:var(--text-2);text-decoration:none;font-size:.93rem;padding:8px 11px;border-radius:8px}
.nav-links a:hover{color:var(--accent)}
.nav-links a.current{color:var(--text);background:var(--bg-light)}
.nav-cta{margin-left:10px}
.menu-btn{display:none;margin-left:auto;background:var(--bg-light);border:1px solid var(--line);color:var(--text);border-radius:10px;padding:8px 12px;cursor:pointer;font:inherit}

/* Blog header */
.blog-hero{padding:28px 0 24px;border-bottom:1px solid var(--line)}
.blog-hero .cta-row{display:flex;flex-wrap:wrap;gap:10px;margin-top:18px}
.blog-hero + .section{padding-top:28px}
.blog-hero .crumb{font-size:.88rem;color:var(--muted);margin:0 0 12px}
.blog-hero .crumb a{color:var(--muted);text-decoration:none}
.blog-hero h1{font-size:clamp(2rem,4.4vw,3.2rem);line-height:1.08;font-weight:800}
.blog-hero p{margin:14px 0 0;max-width:62ch;font-size:1.08rem}
.section{padding-block:56px}

/* Post list */
.post-list{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:22px}
.card{display:flex;flex-direction:column;background:var(--bg-light);border:1px solid var(--line);border-radius:var(--r-lg);overflow:hidden;transition:border-color .2s}
.card:hover{border-color:var(--accent)}
.card-img{display:block;aspect-ratio:16/9;background:var(--bg-dark);overflow:hidden}
.card-img img{width:100%;height:100%;object-fit:cover;display:block}
.card-noimg{aspect-ratio:16/9;background:radial-gradient(circle,rgba(201,209,222,.1) 1px,transparent 1.2px) 0 0/18px 18px,var(--bg-dark);display:grid;place-items:center;color:var(--accent);font-family:var(--display);font-weight:800;font-size:1.6rem;text-decoration:none}
.card-body{padding:18px 18px 20px;display:flex;flex-direction:column;gap:8px;flex:1}
.card time{font-size:.8rem;color:var(--muted)}
.card h2{font-size:1.12rem;line-height:1.35}
.card h2 a{color:var(--text);text-decoration:none}
.card h2 a:hover{color:var(--accent)}
.card p{margin:0;font-size:.92rem;color:var(--muted)}
.card .more{margin-top:auto;padding-top:6px;font-weight:600;font-size:.92rem;text-decoration:none}
.empty{background:var(--bg-light);border:1px dashed var(--line-strong);border-radius:var(--r-lg);padding:28px}

/* Pager */
.pager{display:flex;justify-content:space-between;gap:12px;margin-top:36px}

/* Single post */
.single{max-width:780px;margin:0 auto}
.single-head{padding:48px 0 28px;border-bottom:1px solid var(--line);margin-bottom:32px}
.single-head .crumb{font-size:.88rem;color:var(--muted);margin:0 0 14px}
.single-head .crumb a{color:var(--muted);text-decoration:none}
.single-head h1{font-size:clamp(1.9rem,4vw,2.8rem);line-height:1.15;font-weight:800}
.meta{display:flex;flex-wrap:wrap;gap:10px;align-items:center;margin-top:16px;font-size:.9rem;color:var(--muted)}
.tag{background:var(--bg-light);border:1px solid var(--line);color:var(--accent-soft);padding:3px 11px;border-radius:999px;font-size:.8rem;text-decoration:none}
.post-body{font-size:1.06rem;line-height:1.85;color:var(--text-2);overflow-wrap:anywhere}
.post-body p,.post-body li,.post-body h2,.post-body h3,.post-body blockquote{unicode-bidi:plaintext;text-align:start}
.post-body h2{font-size:1.6rem;margin:1.6em 0 .5em}
.post-body h3{font-size:1.25rem;margin:1.4em 0 .4em}
.post-body img{border-radius:var(--r-md);display:block;margin:1.2em auto}
.post-body a{color:var(--accent)}
.post-body blockquote{margin:1.4em 0;padding:14px 20px;border-inline-start:3px solid var(--accent);background:var(--bg-light);border-radius:0 var(--r-md) var(--r-md) 0}
.post-body pre,.post-body code{background:var(--bg-dark);border-radius:8px;padding:2px 6px;font-size:.92em}
.post-body pre{padding:14px;overflow-x:auto}
.post-body table{display:block;overflow-x:auto;border-collapse:collapse}
.post-body td,.post-body th{border:1px solid var(--line);padding:8px 12px}
.post-body .separator a{margin:0!important}
.post-cta{margin:44px 0 0;padding:28px;border-radius:var(--r-lg);border:1px solid rgba(183,216,148,.45);background:linear-gradient(135deg,rgba(183,216,148,.12),rgba(183,216,148,0) 60%),var(--bg-light);display:grid;gap:14px}
.post-cta h3{font-size:1.35rem}
.post-cta .row{display:flex;flex-wrap:wrap;gap:10px}
.share{display:flex;flex-wrap:wrap;gap:10px;align-items:center;margin-top:28px;font-size:.9rem;color:var(--muted)}

/* Footer (same as site) */
.foot{position:relative;z-index:1;border-top:1px solid var(--line);font-size:.9rem;color:var(--muted);padding-block:48px 28px;direction:ltr}
.foot-grid{display:grid;grid-template-columns:1.3fr 1fr 1fr;gap:36px}
.foot-me{display:flex;gap:16px;align-items:center}
.foot-me img{width:72px;height:72px;border-radius:50%;object-fit:cover;background:#fff;border:2px solid var(--accent);flex:none}
.foot-me strong{display:block;color:var(--text);font-family:var(--display);font-size:1.1rem}
.foot h4{font-size:.95rem;margin-bottom:12px}
.foot ul{list-style:none;margin:0;padding:0;display:grid;gap:8px}
.foot a{color:var(--text-2);text-decoration:none}
.foot a:hover{color:var(--accent)}
.foot-bottom{margin-top:36px;padding-top:20px;border-top:1px solid var(--line);display:flex;justify-content:space-between;gap:12px;flex-wrap:wrap}
.stack{display:grid;gap:16px}

.wa-float{position:fixed;left:calc(20px + env(safe-area-inset-left,0px));bottom:calc(20px + env(safe-area-inset-bottom,0px));width:56px;height:56px;border-radius:50%;background:var(--wa);color:#fff;display:grid;place-items:center;box-shadow:0 8px 24px rgba(0,0,0,.35);z-index:60}

/* Pointer screens (same as site) */
.bg-screens{position:fixed;inset:0;z-index:0;pointer-events:none;overflow:hidden;opacity:0;filter:blur(5px);transition:opacity .45s ease;
  -webkit-mask-image:radial-gradient(circle var(--r,140px) at var(--mx,-999px) var(--my,-999px),#000 0%,rgba(0,0,0,.45) 55%,transparent 100%);
  mask-image:radial-gradient(circle var(--r,140px) at var(--mx,-999px) var(--my,-999px),#000 0%,rgba(0,0,0,.45) 55%,transparent 100%)}
.bg-screens.on{opacity:.32}
.bg-screens .bs-grid{position:absolute;inset:-60px;display:grid;grid-template-columns:repeat(auto-fill,minmax(240px,1fr));gap:22px;padding:22px;transform:translateY(var(--sy,0px))}
.bs{height:170px;border-radius:16px;background:rgba(38,47,66,.9);border:1px solid rgba(183,216,148,.22);padding:12px;display:flex;flex-direction:column;gap:7px;overflow:hidden}
.bs i{display:block;height:9px;border-radius:5px;background:rgba(201,209,222,.18)}
.bs i.g{background:rgba(183,216,148,.55)}.bs i.w{width:60%}.bs i.s{width:38%}.bs i.r{align-self:flex-end;width:55%}
.bs .bb{height:22px;border-radius:9px;background:rgba(201,209,222,.14);width:70%}
.bs .bb.me{align-self:flex-end;background:rgba(183,216,148,.45);width:62%}
.bs .row{display:flex;gap:6px;align-items:center}
.bs .row b{flex:1;height:9px;border-radius:5px;background:rgba(201,209,222,.18)}
.bs .row u{width:34px;height:12px;border-radius:6px;background:rgba(183,216,148,.6)}
.bs .row u.w{background:rgba(242,200,121,.6)}.bs .row u.c{background:rgba(143,179,232,.6)}
.bs .bars{display:flex;align-items:flex-end;gap:6px;height:70px;margin-top:auto}
.bs .bars span{flex:1;border-radius:4px 4px 0 0;background:rgba(183,216,148,.45)}

/* Responsive */
@media (max-width:1120px){
  .menu-btn{display:block}
  .nav-menu{display:none;position:absolute;left:0;right:0;top:68px;background:var(--bg-dark);border-bottom:1px solid var(--line);flex-direction:column;align-items:stretch;padding:12px max(16px,env(safe-area-inset-left,0px)) 18px}
  .nav-menu.open{display:flex}
  .nav-links{flex-direction:column}
  .nav-links a{padding:12px}
  .nav-cta{margin:8px 0 0}
  .foot-grid{grid-template-columns:1fr 1fr}
  .foot-grid > :first-child{grid-column:1/-1}
}
@media (max-width:900px){.post-list{grid-template-columns:repeat(2,minmax(0,1fr))}}
@media (max-width:720px){
  body{font-size:16px}
  .wrap{padding-left:max(16px,env(safe-area-inset-left,0px));padding-right:max(16px,env(safe-area-inset-right,0px))}
  .post-list,.foot-grid{grid-template-columns:1fr}
  .blog-hero{padding:22px 0 20px}
  .blog-hero + .section{padding-top:20px}
  .section{padding-block:36px}
  .single-head{padding:32px 0 22px}
  .wa-float{width:50px;height:50px;left:calc(14px + env(safe-area-inset-left,0px));bottom:calc(16px + env(safe-area-inset-bottom,0px))}
  .foot{padding-bottom:96px}
  .post-cta .row .btn{flex:1 1 0;min-width:0}
}
@media (prefers-reduced-motion:reduce){*,*::before,*::after{transition-duration:.01ms!important;scroll-behavior:auto!important}}

body.script:
//
  (function () {
    "use strict";
    var $$ = function (s) { return Array.prototype.slice.call(document.querySelectorAll(s)); };
    var y = document.getElementById("year"); if (y) y.textContent = new Date().getFullYear();
    // Menu
    var btn = document.querySelector(".menu-btn"), menu = document.getElementById("navMenu");
    if (btn && menu) btn.addEventListener("click", function () {
      var open = menu.classList.toggle("open"); btn.setAttribute("aria-expanded", open ? "true" : "false"); btn.textContent = open ? "Close" : "Menu";
    });
    // WhatsApp clicks: prefilled message + tracking
    $$("[data-wa]").forEach(function (a) {
      a.href = "https://wa.me/971507761628?text=" + encodeURIComponent("Hi Ahmed, I read your blog (" + location.href.split("?")[0] + ") and I'd like to talk.");
      a.addEventListener("click", function () {
        try { if (window.gtag) gtag("event", "whatsapp_click", { page: location.pathname, place: a.getAttribute("data-place") }); } catch (e) {}
        try { if (window.fbq) fbq("track", "Contact"); } catch (e) {}
      });
    });
    // WhatsApp links inside articles: keep their own message, only track the click
    $$(".post-body a[href*='wa.me/971']").forEach(function (a) {
      a.target = "_blank"; a.rel = "noopener";
      a.addEventListener("click", function () {
        try { if (window.gtag) gtag("event", "whatsapp_click", { page: location.pathname, place: "blog-article" }); } catch (e) {}
        try { if (window.fbq) fbq("track", "Contact"); } catch (e) {}
      });
    });
    // Pointer screens
    var layer = document.createElement("div"); layer.className = "bg-screens"; layer.setAttribute("aria-hidden", "true");
    var grid = document.createElement("div"); grid.className = "bs-grid";
    var T = [
      '<div class="bb"></div><div class="bb me"></div><div class="bb"></div><div class="bb me"></div>',
      '<div class="row"><b></b><u></u></div><div class="row"><b></b><u class="w"></u></div><div class="row"><b></b><u></u></div><div class="row"><b></b><u class="c"></u></div><div class="row"><b></b><u class="w"></u></div>',
      '<i class="g s"></i><i></i><i class="w"></i><div class="bars"><span style="height:40%"></span><span style="height:65%"></span><span style="height:50%"></span><span style="height:85%"></span><span style="height:70%"></span><span style="height:95%"></span></div>',
      '<i class="g w"></i><i></i><i></i><i class="w"></i><i class="r g"></i><i class="s"></i>'
    ];
    var n = Math.ceil((window.innerWidth + 120) / 262) * Math.ceil((window.innerHeight + 240) / 192) + 8, html = "";
    for (var k = 0; k < n; k++) html += '<div class="bs">' + T[(k * 7 + Math.floor(k / 5)) % T.length] + "</div>";
    grid.innerHTML = html; layer.appendChild(grid); document.body.insertBefore(layer, document.body.firstChild);
    var x = -999, yy = -999, ticking = false, hideT = null;
    var paint = function () { ticking = false; layer.style.setProperty("--mx", x + "px"); layer.style.setProperty("--my", yy + "px"); grid.style.setProperty("--sy", (-(window.scrollY % 192) * 0.35) + "px"); };
    var queue = function () { if (!ticking) { ticking = true; requestAnimationFrame(paint); } };
    var show = function (cx, cy, touch) { x = cx; yy = cy; layer.classList.add("on"); queue(); clearTimeout(hideT); if (touch) hideT = setTimeout(function () { layer.classList.remove("on"); }, 1400); };
    if (!(window.matchMedia && window.matchMedia("(prefers-reduced-motion: reduce)").matches)) {
      window.addEventListener("pointermove", function (e) { show(e.clientX, e.clientY, e.pointerType !== "mouse"); }, { passive: true });
      window.addEventListener("pointerdown", function (e) { show(e.clientX, e.clientY, e.pointerType !== "mouse"); }, { passive: true });
      window.addEventListener("touchmove", function (e) { var t = e.touches[0]; if (t) show(t.clientX, t.clientY, true); }, { passive: true });
      document.documentElement.addEventListener("mouseleave", function () { layer.classList.remove("on"); });
      window.addEventListener("scroll", queue, { passive: true });
    }
  })();
  //
